import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.jwovEGr5.js";const _=JSON.parse('{"title":"2026级新生入学教育","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"中山大学/新生课程/2026级新生入学教育.md","filePath":"中山大学/新生课程/2026级新生入学教育.md"}'),p={name:"中山大学/新生课程/2026级新生入学教育.md"};function i(n,a,h,l,d,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_2026级新生入学教育" tabindex="-1">2026级新生入学教育 <a class="header-anchor" href="#_2026级新生入学教育" aria-label="Permalink to &quot;2026级新生入学教育&quot;">​</a></h1><p>课程时间：2026.8.22 14:30~17:30</p><p>主讲：王彩萍</p><h2 id="品读大学精神文化-为什么" tabindex="-1">品读大学精神文化（为什么） <a class="header-anchor" href="#品读大学精神文化-为什么" aria-label="Permalink to &quot;品读大学精神文化（为什么）&quot;">​</a></h2><p>英国纽曼、德国洪堡、美国耶鲁</p><p>人才培养、科学研究、社会服务的统一</p><h3 id="大学培养全面发展的人" tabindex="-1">大学培养全面发展的人 <a class="header-anchor" href="#大学培养全面发展的人" aria-label="Permalink to &quot;大学培养全面发展的人&quot;">​</a></h3><p>通专融合、全面发展</p><p>通用教育和专业教育是统一的，不是割裂和对立的</p><h3 id="大学是为未来而存在的" tabindex="-1">大学是为未来而存在的 <a class="header-anchor" href="#大学是为未来而存在的" aria-label="Permalink to &quot;大学是为未来而存在的&quot;">​</a></h3><p>具备学习力（面向未知）、思想力（批判审辨）、行动力（采取有效行动）</p><h2 id="百年中大的历史使命" tabindex="-1">百年中大的历史使命 <a class="header-anchor" href="#百年中大的历史使命" aria-label="Permalink to &quot;百年中大的历史使命&quot;">​</a></h2><p>1924年，孙中山先生手创中大前身广东大学。</p><h2 id="从高中生到大学生" tabindex="-1">从高中生到大学生 <a class="header-anchor" href="#从高中生到大学生" aria-label="Permalink to &quot;从高中生到大学生&quot;">​</a></h2><p>用学习的办法解决学习的问题</p><h2 id="关于ai" tabindex="-1">关于AI <a class="header-anchor" href="#关于ai" aria-label="Permalink to &quot;关于AI&quot;">​</a></h2><p>AI易掌握：高阶计算、多变量逻辑推演</p><p>AI难掌握：无意识动作、本能感知、情感体验</p><p>AI时代人的独特价值</p><p>好奇心与想象力、观察力与感知力、审美力与价值判断力</p><h2 id="中大跨学科" tabindex="-1">中大跨学科 <a class="header-anchor" href="#中大跨学科" aria-label="Permalink to &quot;中大跨学科&quot;">​</a></h2><p><strong>共享专业课</strong></p><p>记为<code>公选</code>，转换认定为<code>专选</code></p><p><strong>三级辅修</strong></p><p>微专业12学分 辅修专业25学分 辅修学士学位40学分</p><p>时间一般在六月份</p><p><strong>转院系专业</strong></p><p>时间一般在三四月份</p><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><p>早进课题组、早进实验室</p>',30)])])}const u=e(p,[["render",i]]);export{_ as __pageData,u as default};
